SELECT h.*, u.user_name FROM health_model_config h LEFT JOIN user u ON u.id = h.user_id
AND (h.is_global = TRUE OR h.user_id = #{visibleTo})
AND h.id = #{id}
AND h.user_id = #{userId}
AND h.name LIKE concat('%',#{name},'%')
AND h.detail LIKE concat('%',#{detail},'%')
AND h.is_global = #{isGlobal}
AND h.unit LIKE concat('%',#{unit},'%')
AND h.symbol LIKE concat('%',#{symbol},'%')
ORDER BY h.id DESC
LIMIT #{current},#{size}

